import{z as o,x as B,o as i,c as d,q as A,j as r,D as e,d as n,s,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"再分配与效率代价","description":"","frontmatter":{"title":"再分配与效率代价","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/redistribution-efficiency.md","filePath":"econ/redistribution-efficiency.md","lastUpdated":1791063341000}'),p={name:"econ/redistribution-efficiency.md"};function c(m,E,u,f,C,D){const t=B("Mermaid");return i(),d("div",null,[E[2]||(E[2]=A('<h1 id="再分配与效率代价" tabindex="-1">再分配与效率代价 <a class="header-anchor" href="#再分配与效率代价" aria-label="Permalink to &quot;再分配与效率代价&quot;">​</a></h1><div class="epigraph"><p>把一美元从高能力转到低能力，桶会漏：漏的是劳动与税基的行为反应，不是转运本身不道德。代价由弹性决定，不能用「再分配无用」把权重设掉。</p><footer>—— Okun, Equality and Efficiency: The Big Tradeoff, 1975；Atkinson and Stiglitz, Lectures on Public Economics；对照 Mirrlees 与 Saez 的充分统计</footer></div><p><a href="/econ/income-tax-incentives">上一课</a>给出激励相容所得税的弹性语言。本课缺口是把那条弹性收成规范权衡：社会福利函数要对齐谁，漏桶漏多少。不重推 Mirrlees 一阶条件。后课社会保障把再分配从当期收入换到生命周期；本课先钉静态的效率代价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Okun 的漏桶：转移一元，到穷人手上不足一元，差额是行政成本与激励。现代公共财政把「激励」写成上一课的税基弹性：边际税提高，机械增益被行为损失抵消一部分。缺口不是再讲一次平均—边际，而是：<strong>福利权重与弹性是两件东西</strong>。权重来自规范（Atkinson 的不平等厌恶、功利、罗尔斯）；弹性来自行为。把弹性估大，用来论证权重应为零，是类别错误；把权重设高，用来否认弹性，同样错误。</p><p>次优已经贯穿 Ramsey：没有一次总付，再分配必须走扭曲工具。第一最佳的福利定理在此本来就不适用——不是市场「突然失效」，是工具集受限。</p><h3 id="效率代价不是再分配无用" tabindex="-1">效率代价不是再分配无用 <a class="header-anchor" href="#效率代价不是再分配无用" aria-label="Permalink to &quot;效率代价不是再分配无用&quot;">​</a></h3><p>「漏了所以别转」漏掉了：目标函数里一元对低收入的权重可以大于一元对高收入。桶漏 20%，若权重比大于 \\(1/0.8\\)，转移仍可提高福利。争论应落在权重与弹性的数字，而不是落在「有漏就停」。行政成本是漏的另一截，与激励不是同一导数，但同进桶。</p><p><span class="marginnote">数字实例：桶漏 20% 意味着转移一元、穷人到手 0.8 元。只要决策者给低收入者一元的价值至少是给高收入者的 \\(1/0.8=1.25\\) 倍，这次转移就提高了社会福利。「漏了仍值得转」是 Okun 隐喻里最常被漏读的一半。</span></p><p><span class="marginnote">Atkinson–Stiglitz 把最优税写成社会福利函数对激励约束。本课用漏桶作翻译，避免把讲义里的 \\(\\lambda\\) 只当成拉格朗日符号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>充分统计：小幅提高某段边际税的福利效应 \\(=(\\)机械转移 \\(\\times\\) 权重差\\()-(\\)税基收缩 \\(\\times\\) 边际公共资金\\()\\)。经验工作估弹性与税率，规范工作选权重；两者分开报告。不平等测度（基尼、Atkinson 指数）是结果指标，不是工具；工具仍是 \\(T(y)\\) 与转移。与公共品：提供 \\(G\\) 也花漏桶里的钱，萨缪尔森条件里的边际公共资金正是这里的漏。标签效应（EITC 对工时、转移对消费）会改变漏的位置，充分统计要写在具体工具上，不能写在「再分配」三个字上。</p>',12)),(i(),r(l,null,{default:e(()=>[s(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E6%89%80%E5%BE%97%E7%A8%8E%E5%BC%B9%E6%80%A7%22%5D%20--%3E%20BUCKET%5B%22%E6%BC%8F%E6%A1%B6%3A%20%E8%A1%8C%E4%B8%BA%E5%8A%A0%E8%A1%8C%E6%94%BF%22%5D%0A%20%20BUCKET%20--%3E%20W%5B%22%E7%A6%8F%E5%88%A9%E6%9D%83%E9%87%8D%22%5D%0A%20%20BUCKET%20--%3E%20E%5B%22%E7%A8%8E%E5%9F%BA%E5%BC%B9%E6%80%A7%22%5D%0A%20%20W%20--%3E%20SS%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%E5%86%8D%E5%88%86%E9%85%8D%22%5D%0A%20%20E%20--%3E%20SS%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"不要用税前基尼下降直接当成功：税前收入已含行为，循环论证。看税后分配与行为调整后的福利。行政成本（申报、稽查、欺诈）是漏的另一截，弹性公式常常省略它；把行政成本当零，会高估给定税率下的净转移。Atkinson 的不平等厌恶参数把权重写成可讨论的数字，避免「公平」停在形容词。",-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"常见误区：容易用「税前基尼下降了」宣布再分配成功。但税前收入本身已经被税收行为改变——高税率压低了报税收入，基尼下降可能只说明大家干活少了，而不是分配变好了。正确的读法是看税后分配和行为调整后的福利，并把行政成本计入漏。")],-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[n("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,"机制是受限工具集下的帕累托边界。再分配沿着激励相容集移动，每一步用弹性标出可行方向的斜率。权重决定沿这条边界停在哪一点。没有弹性，边界是第一最佳的 45° 转移；弹性把边界弯回去。Ramsey 商品税是同一边界在另一组工具上的投影；所得税通常更对准能力，漏可以更小——这是 Atkinson–Stiglitz 弱可分结果的直觉。",-1)),(i(),r(l,null,{default:e(()=>[s(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAKE%5B%22%E5%90%91%E9%AB%98%E6%94%B6%E5%85%A5%E8%80%85%E5%A4%9A%E5%BE%81%201%20%E5%85%83%22%5D%20--%3E%20MECH%5B%22%E6%9C%BA%E6%A2%B0%E8%BD%AC%E7%A7%BB%EF%BC%9A1%20%E5%85%83%E5%85%A5%E6%A1%B6%22%5D%0A%20%20BEHAV%5B%22%E9%AB%98%E6%94%B6%E5%85%A5%E8%80%85%E5%B0%91%E5%B9%B2%E6%B4%BB%E3%80%81%E5%A4%9A%E9%81%BF%E7%A8%8E%22%5D%20--%3E%20LEAK1%5B%22%E8%A1%8C%E4%B8%BA%E6%BC%8F%EF%BC%9A%E7%A8%8E%E5%9F%BA%E6%94%B6%E7%BC%A9%22%5D%0A%20%20ADM%5B%22%E7%94%B3%E6%8A%A5%E3%80%81%E7%A8%BD%E6%9F%A5%E3%80%81%E6%AC%BA%E8%AF%88%22%5D%20--%3E%20LEAK2%5B%22%E8%A1%8C%E6%94%BF%E6%BC%8F%22%5D%0A%20%20MECH%20--%3E%20NET%5B%22%E7%A9%B7%E4%BA%BA%E5%AE%9E%E9%99%85%E5%88%B0%E6%89%8B%20%3D%201%20%E2%88%92%20%E8%A1%8C%E4%B8%BA%E6%BC%8F%20%E2%88%92%20%E8%A1%8C%E6%94%BF%E6%BC%8F%22%5D%0A%20%20LEAK1%20--%3E%20NET%0A%20%20LEAK2%20--%3E%20NET%0A%20%20NET%20--%3E%20JUDGE%5B%22%E6%9D%83%E9%87%8D%E6%AF%94%E5%A4%A7%E4%BA%8E%E6%BC%8F%E7%9A%84%E5%80%92%E6%95%B0%E6%97%B6%EF%BC%8C%E7%A6%8F%E5%88%A9%E4%BB%8D%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=A('<p><span class="marginnote">术语翻译：「边际公共资金」衡量政府多拿到一元的真实社会成本。若桶漏两成，公众为政府手里那一元实际付出约 1.25 元，公共项目的好处就得跟这个加码后的成本比，而不是跟面值一元比——这也是公共品提供与再分配共用同一口漏桶的原因。</span></p><p>政治约束（税率上限、不可对某群征税）把可行集再切一刀，漏桶更漏。那是政治经济学，本课只承认它会改变弹性有效值（避税通道）。动态上，资本与人力资本的积累把静态漏换成增长路径上的另一条代价，本课不把增长理论写完，只禁止用静态漏桶否定一切跨期再分配，或用增长口号取消弹性。</p><p><span class="marginnote">Okun 1975 的隐喻先于充分统计最优税文献，但方向一致：代价是技术性的漏，不是把平等从目标函数里删掉。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不选定一个国家的最优基尼。不把增长理论里的再分配与资本积累写完。动态一致性、资本税留给宏观。下一课：强制年金与社会保障，把再分配从截面换到寿命与收入风险。后课默认：主张或反对某项转移时，同时写权重与弹性；只写其中一项，论证不完整。现金转移与实物转移的漏不同：后者限制用途，代理成本换方向，弹性公式要另写，本课不展开菜单。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>再分配走扭曲工具，漏桶的漏是弹性与行政成本。</li><li>福利权重与行为弹性是两类对象，不能互相取消。</li><li>有漏仍可能提高福利，若权重差大于漏的倒数。</li><li>边际公共资金把漏接到公共品提供。</li><li>行政成本是漏的另一截，与劳动弹性不是同一导数。</li><li>出处：Okun 1975；Atkinson and Stiglitz；Mirrlees；Saez。</li></ul>',7))])}const k=o(p,[["render",c]]);export{T as __pageData,k as default};
